#include <iostream>
using namespace std;

using int64 = long long;

int64 countUpTo(int64 x) {
    if (x <= 0) return 0;

    int64 count = 0;
    for (int length = 2; length <= 63; ++length) {
        for (int zeroPos = 0; zeroPos < length - 1; ++zeroPos) {
            __int128 value = ((__int128)1 << length) - 1;
            value -= ((__int128)1 << zeroPos);
            if (value <= x) ++count;
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    cin >> a >> b;

    cout << countUpTo(b) - countUpTo(a - 1) << '\n';
    return 0;
}

